export function accountsMerge(accounts: string[][]): string[][] {
  const parent=accounts.map((_,i)=>i); function find(i:number):number { while(parent[i]!==i) {parent[i]=parent[parent[i]];i=parent[i];}return i; } const owner=new Map<string,number>();for(let i=0;i<accounts.length;i++)for(const email of accounts[i].slice(1)) {const old=owner.get(email);if(old!==undefined)parent[find(i)]=find(old);else owner.set(email,i);} const groups=new Map<number,Set<string>>();for(let i=0;i<accounts.length;i++) {const root=find(i),emails=groups.get(root)??new Set<string>();for(const email of accounts[i].slice(1))emails.add(email);groups.set(root,emails);} const result=Array.from(groups,([root,emails])=>[accounts[root][0],...Array.from(emails).sort()]);return result.sort((a,b)=>{for(let i=0;i<Math.min(a.length,b.length);i++){if(a[i]<b[i])return -1;if(a[i]>b[i])return 1;}return a.length-b.length;});
}
